     * @return
     */
    private Set<String> getRawRoleNames(Set<GrantedAuthority> grantedAuthorities) {
        Set<String> grantedRoles = new HashSet<String>();
        for (GrantedAuthority auth : grantedAuthorities) {
            grantedRoles.add(auth.getAuthority());
        }
        return grantedRoles;
    }
