cd /tmp/probe; P=./t.sh; R=http://localhost:8081/rest; reset(){ ./reset.sh ref; }; H='Content-Type: application/json'; setup(){ reset; psql -q -d ref -f /tmp/probe/subtypes.sql; }
cat > subtypes.sql <<'EOF'
insert into layerdatasources (id, created, modified, format, name, type, url) values
 (50, now(), now(), 'image/png', 'nm50', 'ImageWMS', 'http://img'),
 (52, now(), now(), null, 'nm52', 'WFS', 'http://wfs'),
 (53, now(), now(), 'image/png', 'nm53', 'WMTS', 'http://wmts'),
 (56, now(), now(), null, 'nm56', 'XYZ', 'http://xyz');
insert into imagewmslayerdatasources (id, height, width, version, layernames, layerstyles, requestablebypath, customrequestpath) values (50, 256, 512, '1.3.0', 'a,b', '', true, '/p');
insert into wfslayerdatasources (id, typename, typenames, version) values (52, 'tn', 'tns', '2.0.0');
insert into extents (id, created, modified, lowerleft_x, lowerleft_y, upperright_x, upperright_y) values (55, now(), now(), -1, -2, 3, 4), (57, now(), now(), 0,0,1,1);
insert into tilegrids (id, created, modified, tilegridorigin_x, tilegridorigin_y, tilesize, type, tilegridextent_id) values (54, now(), now(), 1.5, 2.5, 256, 'WmtsTileGrid', 55);
insert into wmtstilegrids (id) values (54);
insert into wmtstilegrids_matrixids values (54, 'm0'), (54, 'm1');
insert into tilegrid_resolution values (54, 1.0, 0), (54, 0.5, 1);
insert into wmtslayerdatasources (id, capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id) values (53, 'http://cap', 'ms', 'EPSG:3857', 'REST', 'lay', 'sty', 54);
insert into wmtslayerdatasources_urls values (53, 'http://u1'), (53, 'http://u2');
insert into xyzlayerdatasources (id, center_x, center_y, tilesize, extent_id) values (56, 7.5, 8.5, 512, 57);
EOF
setup; echo "k1 PUT imagewms"; LEN=200 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/50 -d '{"id":50,"width":300,"layerNames":"z","type":"T"}'; psql -d ref -At -c 'select * from imagewmslayerdatasources where id=50' -c 'select id,type from layerdatasources where id=50'
setup; echo "k2 PUT wmts urls and wmtsLayer"; LEN=200 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/53 -d '{"id":53,"urls":["http://n1"],"wmtsLayer":"L2"}'; psql -d ref -At -c 'select * from wmtslayerdatasources_urls' -c 'select id,wmtslayer from wmtslayerdatasources'
setup; echo "k3 PUT wmts tileGrid same id 54"; LEN=200 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/53 -d '{"id":53,"tileGrid":{"id":54,"tileSize":100}}'; psql -d ref -At -c 'select * from tilegrids' -c 'select * from wmtstilegrids_matrixids' 
setup; echo "k4 PUT wmts tileGrid new (no id)"; LEN=400 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/53 -d '{"id":53,"tileGrid":{"tileSize":100,"matrixIds":["q"]}}'; psql -d ref -At -c 'select * from tilegrids order by id' -c 'select * from wmtstilegrids' -c 'select * from wmtslayerdatasources'
setup; echo "k5 PUT tilewms 12 tileGrid id 11 (same as current)"; LEN=200 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/12 -d '{"id":12,"tileGrid":{"id":11,"tileSize":300}}'
setup; echo "k6 PUT tilewms 12 requestWithTiled false"; LEN=200 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/12 -d '{"id":12,"requestWithTiled":false}'; psql -d ref -At -c 'select id,request_with_tiled,tilegrid_id from tilewmslayerdatasources'
setup; echo "k7 PUT xyz center"; LEN=300 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/56 -d '{"id":56,"center":{"x":1.25,"y":2},"tileSize":null}'; psql -d ref -At -c 'select * from xyzlayerdatasources'
setup; echo "k8 PUT xyz extent id 55 (not current)"; LEN=300 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/56 -d '{"id":56,"extent":{"id":55}}'; psql -d ref -At -c 'select * from xyzlayerdatasources'
setup; echo "k9 PUT xyz extent new object"; LEN=300 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/56 -d '{"id":56,"extent":{"lowerLeft":{"x":5,"y":6}}}'
setup; echo "k10 PUT wfs"; LEN=300 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/52 -d '{"id":52,"typeName":"x","version":null}'; psql -d ref -At -c 'select * from wfslayerdatasources'
setup; echo "k11 PUT tileGrid extent of tilewms 12 w/o id? (grid 11 extent 10 current)"; LEN=300 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/12 -d '{"id":12,"tileGrid":{"id":12,"tileSize":5}}'
setup; echo "k12 PUT wmts tileGrid with extent id 55 (current) inside new grid"; LEN=300 $P $R -u admin:shogun -H "$H" -X PUT $R/layerdatasources/53 -d '{"id":53,"tileGrid":{"tileSize":9,"tileGridExtent":{"id":55,"lowerLeft":{"x":9,"y":9}}}}'
setup; echo "k13 DELETE wmts source 53 (cascade ALL grid)"; LEN=200 $P $R -u admin:shogun -X DELETE $R/layerdatasources/53; psql -d ref -At -c 'select id from tilegrids' -c 'select id from extents' -c 'select * from wmtslayerdatasources_urls' -c 'select * from wmtstilegrids_matrixids' -c 'select * from tilegrid_resolution'
setup; echo "k14 DELETE xyz 56"; LEN=200 $P $R -u admin:shogun -X DELETE $R/layerdatasources/56; psql -d ref -At -c 'select id from extents order by 1'
setup; echo "k15 DELETE tilewms 12 (used by layer 15)"; LEN=200 $P $R -u admin:shogun -X DELETE $R/layerdatasources/12
setup; echo "k16 DELETE imagewms 50 unreferenced"; LEN=200 $P $R -u admin:shogun -X DELETE $R/layerdatasources/50; psql -d ref -At -c 'select id from layerdatasources order by 1' -c 'select * from imagewmslayerdatasources'
setup; echo "k17 POST layerdatasource"; LEN=200 $P $R -u admin:shogun -H "$H" -X POST $R/layerdatasources -d '{"name":"x"}'
setup; echo "k18 PUT layers 15 source 12 (mirror)"; LEN=200 $P $R -u admin:shogun -H "$H" -X PUT $R/layers/15 -d '{"id":15,"source":null}' ; psql -d ref -At -c 'select id,source_id from layers order by 1'

