//! In-memory entities mirroring the Java model of shogun-core, together with
//! their JSON mapping (Jackson conventions: `null` for absent objects, ids as
//! numbers, unknown properties rejected) and the `output:only` / filter field
//! lists derived from the Java fields.

use serde_json::{json, Map, Value};

/// A JSON body that Jackson would have rejected (or a value it cannot map).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Bad;

pub type Parse<T> = Result<T, Bad>;

/// Properties Jackson silently ignores on every persistent object
/// (`@JsonIgnore` on created/modified and the permission maps).
const IGNORED: &[&str] = &["created", "modified", "userPermissions", "groupPermissions"];

// ---------------------------------------------------------------------------
// Scalar readers, following Jackson's coercions for the Java field types.
// ---------------------------------------------------------------------------

/// Wrapper `Integer`: null -> None, numbers and numeric strings accepted.
pub fn get_int(v: &Value) -> Parse<Option<i32>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i32::try_from(i).map(Some).map_err(|_| Bad)
            } else {
                let f = n.as_f64().ok_or(Bad)?;
                if f.is_finite() && f.abs() < 2_147_483_648.0 {
                    Ok(Some(f.trunc() as i32))
                } else {
                    Err(Bad)
                }
            }
        }
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                Ok(None)
            } else {
                t.parse::<i32>().map(Some).map_err(|_| Bad)
            }
        }
        _ => Err(Bad),
    }
}

/// Primitive `int`: null becomes 0.
pub fn get_int_prim(v: &Value) -> Parse<i32> {
    Ok(get_int(v)?.unwrap_or(0))
}

/// `String`: scalars are converted to their text, containers are rejected.
pub fn get_string(v: &Value) -> Parse<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => Ok(Some(s.clone())),
        Value::Number(n) => Ok(Some(n.to_string())),
        Value::Bool(b) => Ok(Some(b.to_string())),
        _ => Err(Bad),
    }
}

fn parse_bool_text(s: &str) -> Option<bool> {
    if s.eq_ignore_ascii_case("true") {
        Some(true)
    } else if s.eq_ignore_ascii_case("false") {
        Some(false)
    } else {
        None
    }
}

/// Wrapper `Boolean`.
pub fn get_bool(v: &Value) -> Parse<Option<bool>> {
    match v {
        Value::Null => Ok(None),
        Value::Bool(b) => Ok(Some(*b)),
        Value::String(s) => parse_bool_text(s.trim()).map(Some).ok_or(Bad),
        Value::Number(n) => match n.as_i64() {
            Some(0) => Ok(Some(false)),
            Some(1) => Ok(Some(true)),
            _ => Err(Bad),
        },
        _ => Err(Bad),
    }
}

/// Primitive `boolean`: null becomes false.
pub fn get_bool_prim(v: &Value) -> Parse<bool> {
    Ok(get_bool(v)?.unwrap_or(false))
}

/// Wrapper `Double`.
pub fn get_double(v: &Value) -> Parse<Option<f64>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => n.as_f64().map(Some).ok_or(Bad),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                Ok(None)
            } else {
                t.parse::<f64>().map(Some).map_err(|_| Bad)
            }
        }
        _ => Err(Bad),
    }
}

/// Primitive `double`: null becomes 0.0.
pub fn get_double_prim(v: &Value) -> Parse<f64> {
    Ok(get_double(v)?.unwrap_or(0.0))
}

fn get_object(v: &Value) -> Parse<Option<&Map<String, Value>>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(o) => Ok(Some(o)),
        _ => Err(Bad),
    }
}

fn get_list<T>(v: &Value, f: impl Fn(&Value) -> Parse<T>) -> Parse<Option<Vec<T>>> {
    match v {
        Value::Null => Ok(None),
        Value::Array(items) => items.iter().map(&f).collect::<Parse<Vec<T>>>().map(Some),
        _ => Err(Bad),
    }
}

fn non_null_string(v: &Value) -> Parse<String> {
    get_string(v)?.ok_or(Bad)
}

fn non_null_int(v: &Value) -> Parse<i32> {
    get_int(v)?.ok_or(Bad)
}

/// Jackson's `asInt()` as used by the controller for the payload id.
pub fn as_int_lenient(v: &Value) -> i32 {
    match v {
        Value::Number(n) => n.as_i64().map(|i| i as i32).or_else(|| n.as_f64().map(|f| f as i32)).unwrap_or(0),
        Value::String(s) => s.trim().parse::<i32>().unwrap_or(0),
        Value::Bool(b) => i32::from(*b),
        _ => 0,
    }
}

// ---------------------------------------------------------------------------
// Points, extents and tile grids
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Pt {
    pub x: f64,
    pub y: f64,
}

impl Pt {
    fn parse(v: &Value) -> Parse<Option<Pt>> {
        let Some(o) = get_object(v)? else { return Ok(None) };
        let mut p = Pt::default();
        for (k, val) in o {
            match k.as_str() {
                "x" => p.x = get_double_prim(val)?,
                "y" => p.y = get_double_prim(val)?,
                _ => return Err(Bad),
            }
        }
        Ok(Some(p))
    }

    fn json(p: &Option<Pt>) -> Value {
        match p {
            None => Value::Null,
            Some(p) => json!({ "x": p.x, "y": p.y }),
        }
    }

    /// Embedded component: all columns null means the component is null.
    pub fn from_columns(x: Option<f64>, y: Option<f64>) -> Option<Pt> {
        if x.is_none() && y.is_none() {
            None
        } else {
            Some(Pt { x: x.unwrap_or(0.0), y: y.unwrap_or(0.0) })
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct Extent {
    pub id: Option<i32>,
    /// Created by the current request (gets a fresh id and is inserted).
    pub is_new: bool,
    pub lower_left: Option<Pt>,
    pub upper_right: Option<Pt>,
}

impl Extent {
    pub fn parse_fresh(v: &Value) -> Parse<Extent> {
        let mut e = Extent::default();
        e.apply(v.as_object().ok_or(Bad)?)?;
        Ok(e)
    }

    fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "lowerLeft" => self.lower_left = Pt::parse(v)?,
                "upperRight" => self.upper_right = Pt::parse(v)?,
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(e: &Option<Extent>) -> Value {
        match e {
            None => Value::Null,
            Some(e) => json!({
                "id": e.id,
                "lowerLeft": Pt::json(&e.lower_left),
                "upperRight": Pt::json(&e.upper_right),
            }),
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct TileGrid {
    pub id: Option<i32>,
    pub is_new: bool,
    /// Java `WmtsTileGrid` (has a row in `wmtstilegrids`).
    pub is_wmts: bool,
    pub typ: Option<String>,
    pub origin: Option<Pt>,
    pub extent: Option<Extent>,
    pub tile_size: Option<i32>,
    pub resolutions: Option<Vec<f64>>,
    pub matrix_ids: Option<Vec<String>>,
}

impl TileGrid {
    pub fn parse_fresh(v: &Value, is_wmts: bool) -> Parse<TileGrid> {
        let mut g = TileGrid { is_wmts, ..Default::default() };
        g.apply(v.as_object().ok_or(Bad)?)?;
        Ok(g)
    }

    fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "type" => self.typ = get_string(v)?,
                "tileGridOrigin" => self.origin = Pt::parse(v)?,
                "tileGridExtent" => {
                    self.extent = match get_object(v)? {
                        None => None,
                        Some(_) => Some(Extent::parse_fresh(v)?),
                    }
                }
                "tileSize" => self.tile_size = get_int(v)?,
                "tileGridResolutions" => self.resolutions = get_list(v, get_double_prim_nn)?,
                "matrixIds" if self.is_wmts => self.matrix_ids = get_list(v, non_null_string)?,
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(g: &Option<TileGrid>) -> Value {
        match g {
            None => Value::Null,
            Some(g) => {
                let mut m = Map::new();
                m.insert("id".into(), json!(g.id));
                m.insert("type".into(), json!(g.typ));
                m.insert("tileGridOrigin".into(), Pt::json(&g.origin));
                m.insert("tileGridExtent".into(), Extent::json(&g.extent));
                m.insert("tileSize".into(), json!(g.tile_size));
                m.insert("tileGridResolutions".into(), json!(g.resolutions));
                if g.is_wmts {
                    m.insert("matrixIds".into(), json!(g.matrix_ids));
                }
                Value::Object(m)
            }
        }
    }
}

fn get_double_prim_nn(v: &Value) -> Parse<f64> {
    // list elements of Double: a null element is not usable by the persistence layer
    get_double(v)?.ok_or(Bad)
}

// ---------------------------------------------------------------------------
// Users, groups, roles
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Default)]
pub struct Role {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
}

impl Role {
    pub fn parse_fresh(v: &Value) -> Parse<Role> {
        let mut r = Role::default();
        r.apply(v.as_object().ok_or(Bad)?)?;
        Ok(r)
    }

    fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "name" => self.name = get_string(v)?,
                "description" => self.description = get_string(v)?,
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(&self) -> Value {
        json!({ "id": self.id, "name": self.name, "description": self.description })
    }

    pub fn json_list(v: &Option<Vec<Role>>) -> Value {
        match v {
            None => Value::Null,
            Some(list) => Value::Array(list.iter().map(Role::json).collect()),
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct User {
    pub id: Option<i32>,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    /// ISO date text (`yyyy-MM-dd`).
    pub birthday: Option<String>,
    /// Java `Locale.toString()` form, e.g. `de_DE`.
    pub language: Option<String>,
    pub account_name: Option<String>,
    pub password: Option<String>,
    pub active: bool,
    pub roles: Option<Vec<Role>>,
    pub user_groups: Option<Vec<i32>>,
    /// The request set `userGroups` (each id is resolved with a READ check).
    pub touched_groups: bool,
}

impl User {
    pub fn parse_fresh(v: &Value) -> Parse<User> {
        let mut u = User { roles: Some(vec![]), user_groups: Some(vec![]), ..Default::default() };
        u.apply(v.as_object().ok_or(Bad)?)?;
        Ok(u)
    }

    pub fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "firstName" => self.first_name = get_string(v)?,
                "lastName" => self.last_name = get_string(v)?,
                "email" => self.email = get_string(v)?,
                "birthday" => self.birthday = parse_birthday(v)?,
                "language" => self.language = parse_locale(v)?,
                "accountName" => self.account_name = get_string(v)?,
                "password" => self.password = get_string(v)?,
                "active" => self.active = get_bool_prim(v)?,
                "roles" => self.roles = get_list(v, |r| Role::parse_fresh(r))?,
                "userGroups" => {
                    self.user_groups = get_list(v, group_ref_id)?;
                    self.touched_groups = true;
                }
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(&self) -> Value {
        json!({
            "id": self.id,
            "firstName": self.first_name,
            "lastName": self.last_name,
            "email": self.email,
            "birthday": self.birthday,
            "language": self.language,
            "accountName": self.account_name,
            "active": self.active,
            "roles": Role::json_list(&self.roles),
            "userGroups": self.user_groups,
        })
    }

    pub fn json_opt(u: &Option<User>) -> Value {
        match u {
            None => Value::Null,
            Some(u) => u.json(),
        }
    }

    pub fn json_list(v: &Option<Vec<User>>) -> Value {
        match v {
            None => Value::Null,
            Some(list) => Value::Array(list.iter().map(User::json).collect()),
        }
    }
}

/// A `userGroups` element: an id, or an object carrying an id.
fn group_ref_id(v: &Value) -> Parse<i32> {
    match v {
        Value::Number(_) | Value::String(_) => non_null_int(v),
        Value::Object(_) => UserGroup::parse_fresh(v)?.id.ok_or(Bad),
        _ => Err(Bad),
    }
}

fn parse_birthday(v: &Value) -> Parse<Option<String>> {
    match get_string(v)? {
        None => Ok(None),
        Some(s) => {
            let b = s.as_bytes();
            let ok = b.len() == 10
                && b[4] == b'-'
                && b[7] == b'-'
                && b.iter().enumerate().all(|(i, c)| i == 4 || i == 7 || c.is_ascii_digit());
            if ok {
                Ok(Some(s))
            } else {
                Err(Bad)
            }
        }
    }
}

/// Mirrors `java.util.Locale`: language lower-cased, country upper-cased,
/// separators `_` or `-`, and `Locale.toString()` as the stored form.
fn parse_locale(v: &Value) -> Parse<Option<String>> {
    let Some(s) = get_string(v)? else { return Ok(None) };
    let mut parts = s.split(['_', '-']);
    let lang = parts.next().unwrap_or("").to_lowercase();
    let country = parts.next().unwrap_or("").to_uppercase();
    let variant = parts.collect::<Vec<_>>().join("_");
    let mut out = lang;
    if !country.is_empty() {
        out.push('_');
        out.push_str(&country);
    }
    if !variant.is_empty() {
        if country.is_empty() {
            out.push('_');
        }
        out.push('_');
        out.push_str(&variant);
    }
    Ok(Some(out))
}

#[derive(Clone, Debug, Default)]
pub struct UserGroup {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub owner: Option<User>,
    pub members: Option<Vec<User>>,
    pub roles: Option<Vec<Role>>,
}

impl UserGroup {
    pub fn parse_fresh(v: &Value) -> Parse<UserGroup> {
        let mut g = UserGroup { members: Some(vec![]), roles: Some(vec![]), ..Default::default() };
        g.apply(v.as_object().ok_or(Bad)?)?;
        Ok(g)
    }

    pub fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "name" => self.name = get_string(v)?,
                "owner" => {
                    self.owner = match get_object(v)? {
                        None => None,
                        Some(_) => Some(User::parse_fresh(v)?),
                    }
                }
                "members" => self.members = get_list(v, User::parse_fresh)?,
                "roles" => self.roles = get_list(v, Role::parse_fresh)?,
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(&self) -> Value {
        json!({
            "id": self.id,
            "name": self.name,
            "owner": User::json_opt(&self.owner),
            "members": User::json_list(&self.members),
            "roles": Role::json_list(&self.roles),
        })
    }
}

// ---------------------------------------------------------------------------
// Layers
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Default)]
pub struct Appearance {
    pub id: Option<i32>,
    pub is_new: bool,
    pub attribution: Option<String>,
    pub hoverable: Option<bool>,
    pub clickable: Option<bool>,
    pub hover_template: Option<String>,
    pub properties: Option<Map<String, Value>>,
    pub name: Option<String>,
    pub max_resolution: Option<f64>,
    pub min_resolution: Option<f64>,
    pub opacity: Option<f64>,
    pub visible: Option<bool>,
}

impl Appearance {
    pub fn parse_fresh(v: &Value) -> Parse<Appearance> {
        let mut a = Appearance { properties: Some(Map::new()), ..Default::default() };
        a.apply(v.as_object().ok_or(Bad)?)?;
        Ok(a)
    }

    fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "attribution" => self.attribution = get_string(v)?,
                "hoverable" => self.hoverable = get_bool(v)?,
                "clickable" => self.clickable = get_bool(v)?,
                "hoverTemplate" => self.hover_template = get_string(v)?,
                "properties" => {
                    self.properties = match v {
                        Value::Null => None,
                        Value::Object(p) => Some(p.clone()),
                        _ => return Err(Bad),
                    }
                }
                "name" => self.name = get_string(v)?,
                "maxResolution" => self.max_resolution = get_double(v)?,
                "minResolution" => self.min_resolution = get_double(v)?,
                "opacity" => self.opacity = get_double(v)?,
                "visible" => self.visible = get_bool(v)?,
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(&self) -> Value {
        json!({
            "id": self.id,
            "attribution": self.attribution,
            "hoverable": self.hoverable,
            "clickable": self.clickable,
            "hoverTemplate": self.hover_template,
            "properties": self.properties.as_ref().map(|p| Value::Object(p.clone())),
            "name": self.name,
            "maxResolution": self.max_resolution,
            "minResolution": self.min_resolution,
            "opacity": self.opacity,
            "visible": self.visible,
        })
    }

    pub fn json_opt(a: &Option<Appearance>) -> Value {
        match a {
            None => Value::Null,
            Some(a) => a.json(),
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct ImageFields {
    pub width: i32,
    pub height: i32,
    pub version: Option<String>,
    pub layer_names: Option<String>,
    pub layer_styles: Option<String>,
    pub requestable_by_path: Option<bool>,
    pub custom_request_path: Option<String>,
}

#[derive(Clone, Debug)]
pub enum SourceKind {
    ImageWms(ImageFields),
    TileWms {
        img: ImageFields,
        tile_grid: Option<TileGrid>,
        request_with_tiled: Option<bool>,
    },
    Wfs {
        version: Option<String>,
        type_name: Option<String>,
        type_names: Option<String>,
    },
    Wmts {
        tile_grid: Option<TileGrid>,
        urls: Option<Vec<String>>,
        wmts_layer: Option<String>,
        wmts_style: Option<String>,
        projection: Option<String>,
        matrix_set: Option<String>,
        request_encoding: Option<String>,
        capabilities_url: Option<String>,
    },
    Xyz {
        center: Option<Pt>,
        extent: Option<Extent>,
        resolutions: Option<Vec<f64>>,
        tile_size: Option<i32>,
    },
}

/// A `LayerDataSource` row together with its concrete subtype.
#[derive(Clone, Debug)]
pub struct Source {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub typ: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
    pub kind: SourceKind,
    /// The request set `tileGrid` (its grid is written; otherwise untouched).
    pub touched_grid: bool,
}

impl Source {
    pub fn kind_name(&self) -> &'static str {
        match self.kind {
            SourceKind::ImageWms(_) => "ImageWMS",
            SourceKind::TileWms { .. } => "TileWMS",
            SourceKind::Wfs { .. } => "WFS",
            SourceKind::Wmts { .. } => "WMTS",
            SourceKind::Xyz { .. } => "XYZ",
        }
    }

    pub fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            let key = k.as_str();
            match key {
                "id" => self.id = get_int(v)?,
                "name" => self.name = get_string(v)?,
                "type" => self.typ = get_string(v)?,
                "url" => self.url = get_string(v)?,
                "format" => self.format = get_string(v)?,
                _ if IGNORED.contains(&key) => {}
                _ => self.apply_kind(key, v)?,
            }
        }
        Ok(())
    }

    fn apply_kind(&mut self, key: &str, v: &Value) -> Parse<()> {
        match &mut self.kind {
            SourceKind::ImageWms(img) => apply_image(img, key, v),
            SourceKind::TileWms { img, tile_grid, request_with_tiled } => match key {
                "tileGrid" => {
                    self.touched_grid = true;
                    *tile_grid = parse_grid(v, false)?;
                    Ok(())
                }
                "requestWithTiled" => {
                    *request_with_tiled = get_bool(v)?;
                    Ok(())
                }
                _ => apply_image(img, key, v),
            },
            SourceKind::Wfs { version, type_name, type_names } => match key {
                "version" => {
                    *version = get_string(v)?;
                    Ok(())
                }
                "typeName" => {
                    *type_name = get_string(v)?;
                    Ok(())
                }
                "typeNames" => {
                    *type_names = get_string(v)?;
                    Ok(())
                }
                _ => Err(Bad),
            },
            SourceKind::Wmts {
                tile_grid,
                urls,
                wmts_layer,
                wmts_style,
                projection,
                matrix_set,
                request_encoding,
                capabilities_url,
            } => match key {
                "tileGrid" => {
                    self.touched_grid = true;
                    *tile_grid = parse_grid(v, true)?;
                    Ok(())
                }
                "urls" => {
                    *urls = get_list(v, non_null_string)?;
                    Ok(())
                }
                "wmtsLayer" => {
                    *wmts_layer = get_string(v)?;
                    Ok(())
                }
                "wmtsStyle" => {
                    *wmts_style = get_string(v)?;
                    Ok(())
                }
                "projection" => {
                    *projection = get_string(v)?;
                    Ok(())
                }
                "matrixSet" => {
                    *matrix_set = get_string(v)?;
                    Ok(())
                }
                "requestEncoding" => {
                    *request_encoding = get_string(v)?;
                    Ok(())
                }
                "capabilitiesUrl" => {
                    *capabilities_url = get_string(v)?;
                    Ok(())
                }
                _ => Err(Bad),
            },
            SourceKind::Xyz { center, extent, resolutions, tile_size } => match key {
                "center" => {
                    *center = Pt::parse(v)?;
                    Ok(())
                }
                "extent" => {
                    *extent = match get_object(v)? {
                        None => None,
                        Some(_) => Some(Extent::parse_fresh(v)?),
                    };
                    Ok(())
                }
                "resolutions" => {
                    *resolutions = get_list(v, get_double_prim_nn)?;
                    Ok(())
                }
                "tileSize" => {
                    *tile_size = get_int(v)?;
                    Ok(())
                }
                _ => Err(Bad),
            },
        }
    }

    pub fn json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), json!(self.id));
        m.insert("name".into(), json!(self.name));
        m.insert("type".into(), json!(self.typ));
        m.insert("url".into(), json!(self.url));
        m.insert("format".into(), json!(self.format));
        match &self.kind {
            SourceKind::ImageWms(img) => image_json(&mut m, img),
            SourceKind::TileWms { img, tile_grid, request_with_tiled } => {
                image_json(&mut m, img);
                m.insert("tileGrid".into(), TileGrid::json(tile_grid));
                m.insert("requestWithTiled".into(), json!(request_with_tiled));
            }
            SourceKind::Wfs { version, type_name, type_names } => {
                m.insert("version".into(), json!(version));
                m.insert("typeName".into(), json!(type_name));
                m.insert("typeNames".into(), json!(type_names));
            }
            SourceKind::Wmts {
                tile_grid,
                urls,
                wmts_layer,
                wmts_style,
                projection,
                matrix_set,
                request_encoding,
                capabilities_url,
            } => {
                m.insert("tileGrid".into(), TileGrid::json(tile_grid));
                m.insert("urls".into(), json!(urls));
                m.insert("wmtsLayer".into(), json!(wmts_layer));
                m.insert("wmtsStyle".into(), json!(wmts_style));
                m.insert("projection".into(), json!(projection));
                m.insert("matrixSet".into(), json!(matrix_set));
                m.insert("requestEncoding".into(), json!(request_encoding));
                m.insert("capabilitiesUrl".into(), json!(capabilities_url));
            }
            SourceKind::Xyz { center, extent, resolutions, tile_size } => {
                m.insert("center".into(), Pt::json(center));
                m.insert("extent".into(), Extent::json(extent));
                m.insert("resolutions".into(), json!(resolutions));
                m.insert("tileSize".into(), json!(tile_size));
            }
        }
        Value::Object(m)
    }
}

fn parse_grid(v: &Value, is_wmts: bool) -> Parse<Option<TileGrid>> {
    match get_object(v)? {
        None => Ok(None),
        Some(_) => Ok(Some(TileGrid::parse_fresh(v, is_wmts)?)),
    }
}

fn apply_image(img: &mut ImageFields, key: &str, v: &Value) -> Parse<()> {
    match key {
        "width" => img.width = get_int_prim(v)?,
        "height" => img.height = get_int_prim(v)?,
        "version" => img.version = get_string(v)?,
        "layerNames" => img.layer_names = get_string(v)?,
        "layerStyles" => img.layer_styles = get_string(v)?,
        "requestableByPath" => img.requestable_by_path = get_bool(v)?,
        "customRequestPath" => img.custom_request_path = get_string(v)?,
        _ => return Err(Bad),
    }
    Ok(())
}

fn image_json(m: &mut Map<String, Value>, img: &ImageFields) {
    m.insert("width".into(), json!(img.width));
    m.insert("height".into(), json!(img.height));
    m.insert("version".into(), json!(img.version));
    m.insert("layerNames".into(), json!(img.layer_names));
    m.insert("layerStyles".into(), json!(img.layer_styles));
    m.insert("requestableByPath".into(), json!(img.requestable_by_path));
    m.insert("customRequestPath".into(), json!(img.custom_request_path));
}

#[derive(Clone, Debug, Default)]
pub struct Layer {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
    pub source: Option<Source>,
    pub appearance: Option<Appearance>,
    /// The request set `appearance` (the object is written).
    pub touched_appearance: bool,
}

impl Layer {
    pub fn parse_fresh(v: &Value) -> Parse<Layer> {
        let mut l = Layer::default();
        l.apply(v.as_object().ok_or(Bad)?)?;
        Ok(l)
    }

    pub fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "name" => self.name = get_string(v)?,
                "description" => self.description = get_string(v)?,
                // LayerDataSource is abstract: only an explicit null can be bound.
                "source" => match v {
                    Value::Null => self.source = None,
                    _ => return Err(Bad),
                },
                "appearance" => {
                    self.touched_appearance = true;
                    self.appearance = match get_object(v)? {
                        None => None,
                        Some(_) => Some(Appearance::parse_fresh(v)?),
                    }
                }
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(&self) -> Value {
        json!({
            "id": self.id,
            "name": self.name,
            "description": self.description,
            "source": match &self.source { None => Value::Null, Some(s) => s.json() },
            "appearance": Appearance::json_opt(&self.appearance),
        })
    }
}

// ---------------------------------------------------------------------------
// Resource descriptors: field lists for `output:only` and `filter`
// ---------------------------------------------------------------------------

/// Java field types that the filter converts request strings to.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FType {
    Int,
    Str,
    /// primitive `boolean`
    BoolPrim,
    /// wrapper `Boolean`
    BoolW,
    /// wrapper `Double`
    Dbl,
}

#[derive(Clone, Debug, PartialEq)]
pub enum FVal {
    Int(Option<i32>),
    Str(Option<String>),
    Bool(Option<bool>),
    Dbl(Option<f64>),
}

pub const USER_FIELDS: &[(&str, FType)] = &[
    ("id", FType::Int),
    ("firstName", FType::Str),
    ("lastName", FType::Str),
    ("email", FType::Str),
    ("accountName", FType::Str),
    ("password", FType::Str),
    ("active", FType::BoolPrim),
];

pub const GROUP_FIELDS: &[(&str, FType)] = &[("id", FType::Int), ("name", FType::Str)];

pub const ROLE_FIELDS: &[(&str, FType)] =
    &[("id", FType::Int), ("name", FType::Str), ("description", FType::Str)];

pub const LAYER_FIELDS: &[(&str, FType)] =
    &[("id", FType::Int), ("name", FType::Str), ("description", FType::Str)];

pub const SOURCE_FIELDS: &[(&str, FType)] = &[
    ("id", FType::Int),
    ("name", FType::Str),
    ("type", FType::Str),
    ("url", FType::Str),
    ("format", FType::Str),
];

pub const APPEARANCE_FIELDS: &[(&str, FType)] = &[
    ("id", FType::Int),
    ("attribution", FType::Str),
    ("hoverable", FType::BoolW),
    ("clickable", FType::BoolW),
    ("hoverTemplate", FType::Str),
    ("name", FType::Str),
    ("maxResolution", FType::Dbl),
    ("minResolution", FType::Dbl),
    ("opacity", FType::Dbl),
    ("visible", FType::BoolW),
];

impl User {
    pub fn field(&self, name: &str) -> FVal {
        match name {
            "id" => FVal::Int(self.id),
            "firstName" => FVal::Str(self.first_name.clone()),
            "lastName" => FVal::Str(self.last_name.clone()),
            "email" => FVal::Str(self.email.clone()),
            "accountName" => FVal::Str(self.account_name.clone()),
            "password" => FVal::Str(self.password.clone()),
            "active" => FVal::Bool(Some(self.active)),
            _ => FVal::Str(None),
        }
    }

    /// The bean the Java restricted query builds: only the projected fields
    /// are set, every other field keeps its constructor default.
    pub fn project(&self, fields: &[&str]) -> User {
        let mut u = User { roles: Some(vec![]), user_groups: Some(vec![]), ..Default::default() };
        for f in fields {
            match *f {
                "id" => u.id = self.id,
                "firstName" => u.first_name = self.first_name.clone(),
                "lastName" => u.last_name = self.last_name.clone(),
                "email" => u.email = self.email.clone(),
                "accountName" => u.account_name = self.account_name.clone(),
                "password" => u.password = self.password.clone(),
                "active" => u.active = self.active,
                _ => {}
            }
        }
        u
    }
}

impl UserGroup {
    pub fn field(&self, name: &str) -> FVal {
        match name {
            "id" => FVal::Int(self.id),
            "name" => FVal::Str(self.name.clone()),
            _ => FVal::Str(None),
        }
    }

    pub fn project(&self, fields: &[&str]) -> UserGroup {
        let mut g = UserGroup { members: Some(vec![]), roles: Some(vec![]), ..Default::default() };
        for f in fields {
            match *f {
                "id" => g.id = self.id,
                "name" => g.name = self.name.clone(),
                _ => {}
            }
        }
        g
    }
}

impl Role {
    pub fn field(&self, name: &str) -> FVal {
        match name {
            "id" => FVal::Int(self.id),
            "name" => FVal::Str(self.name.clone()),
            "description" => FVal::Str(self.description.clone()),
            _ => FVal::Str(None),
        }
    }

    pub fn project(&self, fields: &[&str]) -> Role {
        let mut r = Role::default();
        for f in fields {
            match *f {
                "id" => r.id = self.id,
                "name" => r.name = self.name.clone(),
                "description" => r.description = self.description.clone(),
                _ => {}
            }
        }
        r
    }
}

impl Layer {
    pub fn field(&self, name: &str) -> FVal {
        match name {
            "id" => FVal::Int(self.id),
            "name" => FVal::Str(self.name.clone()),
            "description" => FVal::Str(self.description.clone()),
            _ => FVal::Str(None),
        }
    }

    pub fn project(&self, fields: &[&str]) -> Layer {
        let mut l = Layer::default();
        for f in fields {
            match *f {
                "id" => l.id = self.id,
                "name" => l.name = self.name.clone(),
                "description" => l.description = self.description.clone(),
                _ => {}
            }
        }
        l
    }
}

impl Source {
    pub fn field(&self, name: &str) -> FVal {
        match name {
            "id" => FVal::Int(self.id),
            "name" => FVal::Str(self.name.clone()),
            "type" => FVal::Str(self.typ.clone()),
            "url" => FVal::Str(self.url.clone()),
            "format" => FVal::Str(self.format.clone()),
            _ => FVal::Str(None),
        }
    }
}

impl Appearance {
    pub fn field(&self, name: &str) -> FVal {
        match name {
            "id" => FVal::Int(self.id),
            "attribution" => FVal::Str(self.attribution.clone()),
            "hoverable" => FVal::Bool(self.hoverable),
            "clickable" => FVal::Bool(self.clickable),
            "hoverTemplate" => FVal::Str(self.hover_template.clone()),
            "name" => FVal::Str(self.name.clone()),
            "maxResolution" => FVal::Dbl(self.max_resolution),
            "minResolution" => FVal::Dbl(self.min_resolution),
            "opacity" => FVal::Dbl(self.opacity),
            "visible" => FVal::Bool(self.visible),
            _ => FVal::Str(None),
        }
    }

    pub fn project(&self, fields: &[&str]) -> Appearance {
        let mut a = Appearance { properties: Some(Map::new()), ..Default::default() };
        for f in fields {
            match *f {
                "id" => a.id = self.id,
                "attribution" => a.attribution = self.attribution.clone(),
                "hoverable" => a.hoverable = self.hoverable,
                "clickable" => a.clickable = self.clickable,
                "hoverTemplate" => a.hover_template = self.hover_template.clone(),
                "name" => a.name = self.name.clone(),
                "maxResolution" => a.max_resolution = self.max_resolution,
                "minResolution" => a.min_resolution = self.min_resolution,
                "opacity" => a.opacity = self.opacity,
                "visible" => a.visible = self.visible,
                _ => {}
            }
        }
        a
    }
}

tool_use_result.content:
//! In-memory entities mirroring the Java model of shogun-core, together with
//! their JSON mapping (Jackson conventions: `null` for absent objects, ids as
//! numbers, unknown properties rejected) and the `output:only` / filter field
//! lists derived from the Java fields.

use serde_json::{json, Map, Value};

/// A JSON body that Jackson would have rejected (or a value it cannot map).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Bad;

pub type Parse<T> = Result<T, Bad>;

/// Properties Jackson silently ignores on every persistent object
/// (`@JsonIgnore` on created/modified and the permission maps).
const IGNORED: &[&str] = &["created", "modified", "userPermissions", "groupPermissions"];

// ---------------------------------------------------------------------------
// Scalar readers, following Jackson's coercions for the Java field types.
// ---------------------------------------------------------------------------

/// Wrapper `Integer`: null -> None, numbers and numeric strings accepted.
pub fn get_int(v: &Value) -> Parse<Option<i32>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i32::try_from(i).map(Some).map_err(|_| Bad)
            } else {
                let f = n.as_f64().ok_or(Bad)?;
                if f.is_finite() && f.abs() < 2_147_483_648.0 {
                    Ok(Some(f.trunc() as i32))
                } else {
                    Err(Bad)
                }
            }
        }
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                Ok(None)
            } else {
                t.parse::<i32>().map(Some).map_err(|_| Bad)
            }
        }
        _ => Err(Bad),
    }
}

/// Primitive `int`: null becomes 0.
pub fn get_int_prim(v: &Value) -> Parse<i32> {
    Ok(get_int(v)?.unwrap_or(0))
}

/// `String`: scalars are converted to their text, containers are rejected.
pub fn get_string(v: &Value) -> Parse<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => Ok(Some(s.clone())),
        Value::Number(n) => Ok(Some(n.to_string())),
        Value::Bool(b) => Ok(Some(b.to_string())),
        _ => Err(Bad),
    }
}

fn parse_bool_text(s: &str) -> Option<bool> {
    if s.eq_ignore_ascii_case("true") {
        Some(true)
    } else if s.eq_ignore_ascii_case("false") {
        Some(false)
    } else {
        None
    }
}

/// Wrapper `Boolean`.
pub fn get_bool(v: &Value) -> Parse<Option<bool>> {
    match v {
        Value::Null => Ok(None),
        Value::Bool(b) => Ok(Some(*b)),
        Value::String(s) => parse_bool_text(s.trim()).map(Some).ok_or(Bad),
        Value::Number(n) => match n.as_i64() {
            Some(0) => Ok(Some(false)),
            Some(1) => Ok(Some(true)),
            _ => Err(Bad),
        },
        _ => Err(Bad),
    }
}

/// Primitive `boolean`: null becomes false.
pub fn get_bool_prim(v: &Value) -> Parse<bool> {
    Ok(get_bool(v)?.unwrap_or(false))
}

/// Wrapper `Double`.
pub fn get_double(v: &Value) -> Parse<Option<f64>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => n.as_f64().map(Some).ok_or(Bad),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                Ok(None)
            } else {
                t.parse::<f64>().map(Some).map_err(|_| Bad)
            }
        }
        _ => Err(Bad),
    }
}

/// Primitive `double`: null becomes 0.0.
pub fn get_double_prim(v: &Value) -> Parse<f64> {
    Ok(get_double(v)?.unwrap_or(0.0))
}

fn get_object(v: &Value) -> Parse<Option<&Map<String, Value>>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(o) => Ok(Some(o)),
        _ => Err(Bad),
    }
}

fn get_list<T>(v: &Value, f: impl Fn(&Value) -> Parse<T>) -> Parse<Option<Vec<T>>> {
    match v {
        Value::Null => Ok(None),
        Value::Array(items) => items.iter().map(&f).collect::<Parse<Vec<T>>>().map(Some),
        _ => Err(Bad),
    }
}

fn non_null_string(v: &Value) -> Parse<String> {
    get_string(v)?.ok_or(Bad)
}

fn non_null_int(v: &Value) -> Parse<i32> {
    get_int(v)?.ok_or(Bad)
}

/// Jackson's `asInt()` as used by the controller for the payload id.
pub fn as_int_lenient(v: &Value) -> i32 {
    match v {
        Value::Number(n) => n.as_i64().map(|i| i as i32).or_else(|| n.as_f64().map(|f| f as i32)).unwrap_or(0),
        Value::String(s) => s.trim().parse::<i32>().unwrap_or(0),
        Value::Bool(b) => i32::from(*b),
        _ => 0,
    }
}

// ---------------------------------------------------------------------------
// Points, extents and tile grids
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Pt {
    pub x: f64,
    pub y: f64,
}

impl Pt {
    fn parse(v: &Value) -> Parse<Option<Pt>> {
        let Some(o) = get_object(v)? else { return Ok(None) };
        let mut p = Pt::default();
        for (k, val) in o {
            match k.as_str() {
                "x" => p.x = get_double_prim(val)?,
                "y" => p.y = get_double_prim(val)?,
                _ => return Err(Bad),
            }
        }
        Ok(Some(p))
    }

    fn json(p: &Option<Pt>) -> Value {
        match p {
            None => Value::Null,
            Some(p) => json!({ "x": p.x, "y": p.y }),
        }
    }

    /// Embedded component: all columns null means the component is null.
    pub fn from_columns(x: Option<f64>, y: Option<f64>) -> Option<Pt> {
        if x.is_none() && y.is_none() {
            None
        } else {
            Some(Pt { x: x.unwrap_or(0.0), y: y.unwrap_or(0.0) })
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct Extent {
    pub id: Option<i32>,
    /// Created by the current request (gets a fresh id and is inserted).
    pub is_new: bool,
    pub lower_left: Option<Pt>,
    pub upper_right: Option<Pt>,
}

impl Extent {
    pub fn parse_fresh(v: &Value) -> Parse<Extent> {
        let mut e = Extent::default();
        e.apply(v.as_object().ok_or(Bad)?)?;
        Ok(e)
    }

    fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "lowerLeft" => self.lower_left = Pt::parse(v)?,
                "upperRight" => self.upper_right = Pt::parse(v)?,
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(e: &Option<Extent>) -> Value {
        match e {
            None => Value::Null,
            Some(e) => json!({
                "id": e.id,
                "lowerLeft": Pt::json(&e.lower_left),
                "upperRight": Pt::json(&e.upper_right),
            }),
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct TileGrid {
    pub id: Option<i32>,
    pub is_new: bool,
    /// Java `WmtsTileGrid` (has a row in `wmtstilegrids`).
    pub is_wmts: bool,
    pub typ: Option<String>,
    pub origin: Option<Pt>,
    pub extent: Option<Extent>,
    pub tile_size: Option<i32>,
    pub resolutions: Option<Vec<f64>>,
    pub matrix_ids: Option<Vec<String>>,
}

impl TileGrid {
    pub fn parse_fresh(v: &Value, is_wmts: bool) -> Parse<TileGrid> {
        let mut g = TileGrid { is_wmts, ..Default::default() };
        g.apply(v.as_object().ok_or(Bad)?)?;
        Ok(g)
    }

    fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "type" => self.typ = get_string(v)?,
                "tileGridOrigin" => self.origin = Pt::parse(v)?,
                "tileGridExtent" => {
                    self.extent = match get_object(v)? {
                        None => None,
                        Some(_) => Some(Extent::parse_fresh(v)?),
                    }
                }
                "tileSize" => self.tile_size = get_int(v)?,
                "tileGridResolutions" => self.resolutions = get_list(v, get_double_prim_nn)?,
                "matrixIds" if self.is_wmts => self.matrix_ids = get_list(v, non_null_string)?,
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(g: &Option<TileGrid>) -> Value {
        match g {
            None => Value::Null,
            Some(g) => {
                let mut m = Map::new();
                m.insert("id".into(), json!(g.id));
                m.insert("type".into(), json!(g.typ));
                m.insert("tileGridOrigin".into(), Pt::json(&g.origin));
                m.insert("tileGridExtent".into(), Extent::json(&g.extent));
                m.insert("tileSize".into(), json!(g.tile_size));
                m.insert("tileGridResolutions".into(), json!(g.resolutions));
                if g.is_wmts {
                    m.insert("matrixIds".into(), json!(g.matrix_ids));
                }
                Value::Object(m)
            }
        }
    }
}

fn get_double_prim_nn(v: &Value) -> Parse<f64> {
    // list elements of Double: a null element is not usable by the persistence layer
    get_double(v)?.ok_or(Bad)
}

// ---------------------------------------------------------------------------
// Users, groups, roles
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Default)]
pub struct Role {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub description: Option<String>,
}

impl Role {
    pub fn parse_fresh(v: &Value) -> Parse<Role> {
        let mut r = Role::default();
        r.apply(v.as_object().ok_or(Bad)?)?;
        Ok(r)
    }

    fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "name" => self.name = get_string(v)?,
                "description" => self.description = get_string(v)?,
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(&self) -> Value {
        json!({ "id": self.id, "name": self.name, "description": self.description })
    }

    pub fn json_list(v: &Option<Vec<Role>>) -> Value {
        match v {
            None => Value::Null,
            Some(list) => Value::Array(list.iter().map(Role::json).collect()),
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct User {
    pub id: Option<i32>,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    /// ISO date text (`yyyy-MM-dd`).
    pub birthday: Option<String>,
    /// Java `Locale.toString()` form, e.g. `de_DE`.
    pub language: Option<String>,
    pub account_name: Option<String>,
    pub password: Option<String>,
    pub active: bool,
    pub roles: Option<Vec<Role>>,
    pub user_groups: Option<Vec<i32>>,
    /// The request set `userGroups` (each id is resolved with a READ check).
    pub touched_groups: bool,
}

impl User {
    pub fn parse_fresh(v: &Value) -> Parse<User> {
        let mut u = User { roles: Some(vec![]), user_groups: Some(vec![]), ..Default::default() };
        u.apply(v.as_object().ok_or(Bad)?)?;
        Ok(u)
    }

    pub fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            match k.as_str() {
                "id" => self.id = get_int(v)?,
                "firstName" => self.first_name = get_string(v)?,
                "lastName" => self.last_name = get_string(v)?,
                "email" => self.email = get_string(v)?,
                "birthday" => self.birthday = parse_birthday(v)?,
                "language" => self.language = parse_locale(v)?,
                "accountName" => self.account_name = get_string(v)?,
                "password" => self.password = get_string(v)?,
                "active" => self.active = get_bool_prim(v)?,
                "roles" => self.roles = get_list(v, |r| Role::parse_fresh(r))?,
                "userGroups" => {
                    self.user_groups = get_list(v, group_ref_id)?;
                    self.touched_groups = true;
                }
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(&self) -> Value {
        json!({
            "id": self.id,
            "firstName": self.first_name,
            "lastName": self.last_name,
            "email": self.email,
            "birthday": self.birthday,
            "language": self.language,
            "accountName": self.account_name,
            "active": self.active,
            "roles": Role::json_list(&self.roles),
            "userGroups": self.user_groups,
        })
    }

    pub fn json_opt(u: &Option<User>) -> Value {
        match u {
            None => Value::Null,
            Some(u) => u.json(),
        }
    }

    pub fn json_list(v: &Option<Vec<User>>) -> Value {
        match v {
            None => Value::Null,
            Some(list) => Value::Array(list.iter().map(User::json).collect()),
        }
    }
}

/// A `userGroups` element: an id, or an object carrying an id.
fn group_ref_id(v: &Value) -> Parse<i32> {
    match v {
        Value::Number(_) | Value::String(_) => non_null_int(v),
        Value::Object(_) => UserGroup::parse_fresh(v)?.id.ok_or(Bad),
        _ => Err(Bad),
    }
}

fn parse_birthday(v: &Value) -> Parse<Option<String>> {
    match get_string(v)? {
        None => Ok(None),
        Some(s) => {
            let b = s.as_bytes();
            let ok = b.len() == 10
                && b[4] == b'-'
                && b[7] == b'-'
                && b.iter().enumerate().all(|(i, c)| i == 4 || i == 7 || c.is_ascii_digit());
            if ok {
                Ok(Some(s))
            } else {
                Err(Bad)
            }
        }
    }
}

/// Mirrors `java.util.Locale`: language lower-cased, country upper-cased,
/// separators `_` or `-`, and `Locale.toString()` as the stored form.
fn parse_locale(v: &Value) -> Parse<Option<String>> {
    let Some(s) = get_string(v)? else { return Ok(None) };
    let mut parts = s.split(['_', '-']);
    let lang = parts.next().unwrap_or("").to_lowercase();
    let country = parts.next().unwrap_or("").to_uppercase();
    let variant = parts.collect::<Vec<_>>().join("_");
    let mut out = lang;
    if !country.is_empty() {
        out.push('_');
        out.push_str(&country);
    }
    if !variant.is_empty() {
        if country.is_empty() {
            out.push('_');
        }
        out.push('_');
        out.push_str(&variant);
    }
    Ok(Some(out))
}

