/// A `LayerDataSource` row together with its concrete subtype.
#[derive(Clone, Debug)]
pub struct Source {
    pub id: Option<i32>,
    pub name: Option<String>,
    pub typ: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
    pub kind: SourceKind,
    /// The request set `tileGrid` (its grid is written; otherwise untouched).
    pub touched_grid: bool,
}

impl Source {
    pub fn kind_name(&self) -> &'static str {
        match self.kind {
            SourceKind::ImageWms(_) => "ImageWMS",
            SourceKind::TileWms { .. } => "TileWMS",
            SourceKind::Wfs { .. } => "WFS",
            SourceKind::Wmts { .. } => "WMTS",
            SourceKind::Xyz { .. } => "XYZ",
        }
    }

    pub fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        for (k, v) in o {
            let key = k.as_str();
            match key {
                "id" => self.id = get_int(v)?,
                "name" => self.name = get_string(v)?,
                "type" => self.typ = get_string(v)?,
                "url" => self.url = get_string(v)?,
                "format" => self.format = get_string(v)?,
                _ if IGNORED.contains(&key) => {}
                _ => self.apply_kind(key, v)?,
            }
        }
        Ok(())
    }

    fn apply_kind(&mut self, key: &str, v: &Value) -> Parse<()> {
        match &mut self.kind {
            SourceKind::ImageWms(img) => apply_image(img, key, v),
            SourceKind::TileWms { img, tile_grid, request_with_tiled } => match key {
                "tileGrid" => {
                    self.touched_grid = true;
                    *tile_grid = parse_grid(v, false)?;
                    Ok(())
                }
                "requestWithTiled" => {
                    *request_with_tiled = get_bool(v)?;
                    Ok(())
                }
                _ => apply_image(img, key, v),
            },
            SourceKind::Wfs { version, type_name, type_names } => match key {
                "version" => {
                    *version = get_string(v)?;
                    Ok(())
                }
                "typeName" => {
                    *type_name = get_string(v)?;
                    Ok(())
                }
                "typeNames" => {
                    *type_names = get_string(v)?;
                    Ok(())
                }
                _ => Err(Bad),
            },
            SourceKind::Wmts {
                tile_grid,
                urls,
                wmts_layer,
                wmts_style,
                projection,
                matrix_set,
                request_encoding,
                capabilities_url,
            } => match key {
                "tileGrid" => {
                    self.touched_grid = true;
                    *tile_grid = parse_grid(v, true)?;
                    Ok(())
                }
                "urls" => {
                    *urls = get_list(v, non_null_string)?;
                    Ok(())
                }
                "wmtsLayer" => {
                    *wmts_layer = get_string(v)?;
                    Ok(())
                }
                "wmtsStyle" => {
                    *wmts_style = get_string(v)?;
                    Ok(())
                }
                "projection" => {
                    *projection = get_string(v)?;
                    Ok(())
                }
                "matrixSet" => {
                    *matrix_set = get_string(v)?;
                    Ok(())
                }
                "requestEncoding" => {
                    *request_encoding = get_string(v)?;
                    Ok(())
                }
                "capabilitiesUrl" => {
                    *capabilities_url = get_string(v)?;
                    Ok(())
                }
                _ => Err(Bad),
            },
            SourceKind::Xyz { center, extent, resolutions, tile_size } => match key {
                "center" => {
                    *center = Pt::parse(v)?;
                    Ok(())
                }
                "extent" => {
                    *extent = match get_object(v)? {
                        None => None,
                        Some(_) => Some(Extent::parse_fresh(v)?),
                    };
                    Ok(())
                }
                "resolutions" => {
                    *resolutions = get_list(v, get_double_prim_nn)?;
                    Ok(())
                }
                "tileSize" => {
                    *tile_size = get_int(v)?;
                    Ok(())
                }
                _ => Err(Bad),
            },
        }
    }

    pub fn json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), json!(self.id));
        m.insert("name".into(), json!(self.name));
        m.insert("type".into(), json!(self.typ));
        m.insert("url".into(), json!(self.url));
        m.insert("format".into(), json!(self.format));
        match &self.kind {
            SourceKind::ImageWms(img) => image_json(&mut m, img),
            SourceKind::TileWms { img, tile_grid, request_with_tiled } => {
                image_json(&mut m, img);
                m.insert("tileGrid".into(), TileGrid::json(tile_grid));
                m.insert("requestWithTiled".into(), json!(request_with_tiled));
            }
            SourceKind::Wfs { version, type_name, type_names } => {
                m.insert("version".into(), json!(version));
                m.insert("typeName".into(), json!(type_name));
                m.insert("typeNames".into(), json!(type_names));
            }
            SourceKind::Wmts {
                tile_grid,
                urls,
                wmts_layer,
                wmts_style,
                projection,
                matrix_set,
                request_encoding,
                capabilities_url,
            } => {
                m.insert("tileGrid".into(), TileGrid::json(tile_grid));
                m.insert("urls".into(), json!(urls));
                m.insert("wmtsLayer".into(), json!(wmts_layer));
                m.insert("wmtsStyle".into(), json!(wmts_style));
                m.insert("projection".into(), json!(projection));
                m.insert("matrixSet".into(), json!(matrix_set));
                m.insert("requestEncoding".into(), json!(request_encoding));
                m.insert("capabilitiesUrl".into(), json!(capabilities_url));
            }
            SourceKind::Xyz { center, extent, resolutions, tile_size } => {
                m.insert("center".into(), Pt::json(center));
                m.insert("extent".into(), Extent::json(extent));
                m.insert("resolutions".into(), json!(resolutions));
                m.insert("tileSize".into(), json!(tile_size));
            }
        }
        Value::Object(m)
    }
}

fn parse_grid(v: &Value, is_wmts: bool) -> Parse<Option<TileGrid>> {
    match get_object(v)? {
        None => Ok(None),
        Some(_) => Ok(Some(TileGrid::parse_fresh(v, is_wmts)?)),
    }
}

fn apply_image(img: &mut ImageFields, key: &str, v: &Value) -> Parse<()> {
    match key {
        "width" => img.width = get_int_prim(v)?,
        "height" => img.height = get_int_prim(v)?,
        "version" => img.version = get_string(v)?,
        "layerNames" => img.layer_names = get_string(v)?,
        "layerStyles" => img.layer_styles = get_string(v)?,
        "requestableByPath" => img.requestable_by_path = get_bool(v)?,
        "customRequestPath" => img.custom_request_path = get_string(v)?,
        _ => return Err(Bad),
    }
    Ok(())
}

fn image_json(m: &mut Map<String, Value>, img: &ImageFields) {
    m.insert("width".into(), json!(img.width));
    m.insert("height".into(), json!(img.height));
    m.insert("version".into(), json!(img.version));
    m.insert("layerNames".into(), json!(img.layer_names));
    m.insert("layerStyles".into(), json!(img.layer_styles));
    m.insert("requestableByPath".into(), json!(img.requestable_by_path));
    m.insert("customRequestPath".into(), json!(img.custom_request_path));
}

