                "id" => self.id = get_int(v)?,
                "name" => self.name = get_string(v)?,
                "description" => self.description = get_string(v)?,
                // LayerDataSource is abstract: only an explicit null can be bound.
                "source" => match v {
                    Value::Null => self.source = None,
                    _ => return Err(Bad),
                },
                "appearance" => {
                    self.touched_appearance = true;
                    self.appearance = match get_object(v)? {
                        None => None,
                        Some(_) => Some(Appearance::parse_fresh(v)?),
                    }
                }
                _ if IGNORED.contains(&k.as_str()) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }

    pub fn json(&self) -> Value {
        json!({
            "id": self.id,
            "name": self.name,
            "description": self.description,
            "source": match &self.source { None => Value::Null, Some(s) => s.json() },
            "appearance": Appearance::json_opt(&self.appearance),
        })
    }
}

