//! Entity permissions, as decided by `ShogunCorePermissionEvaluator` and the
//! `security.access.entity` evaluators of shogun-core.

use anyhow::Result;
use sqlx::PgConnection;

#[derive(Clone, Debug)]
pub struct Principal {
    pub id: i32,
    pub admin: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    User,
    Group,
    Role,
    Layer,
    Source,
    Appearance,
    Map,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Perm {
    Read,
    Update,
    Delete,
}

impl Perm {
    fn name(self) -> &'static str {
        match self {
            Perm::Read => "READ",
            Perm::Update => "UPDATE",
            Perm::Delete => "DELETE",
        }
    }
}

/// Whether `p` holds `perm` on the entity `(kind, id)`.
///
/// * the super admin role is allowed everything;
/// * a user may READ itself; a group member may READ the group;
/// * roles, appearances, data sources and maps are READ for everyone
///   (`AlwaysAllowReadPermissionEvaluator`);
/// * otherwise the entity's user and group permission collections decide
///   (`PersistentObjectPermissionEvaluator`), where `ADMIN` implies all.
pub async fn allowed(c: &mut PgConnection, p: &Principal, kind: Kind, id: i32, perm: Perm) -> Result<bool> {
    if p.admin {
        return Ok(true);
    }
    match (kind, perm) {
        (Kind::User, Perm::Read) if p.id == id => return Ok(true),
        (Kind::Group, Perm::Read) => {
            let member: Option<(i32,)> =
                sqlx::query_as("SELECT 1 FROM user_usergroup WHERE usergroup_id = $1 AND user_id = $2")
                    .bind(id)
                    .bind(p.id)
                    .fetch_optional(&mut *c)
                    .await?;
            if member.is_some() {
                return Ok(true);
            }
        }
        (Kind::Role | Kind::Appearance | Kind::Source | Kind::Map, Perm::Read) => return Ok(true),
        _ => {}
    }
    let perms = vec!["ADMIN".to_string(), perm.name().to_string()];
    let user_hit: Option<(i32,)> = sqlx::query_as(
        "SELECT 1 FROM userpermissions up
           JOIN permissioncollections_permissions pp ON pp.permissioncollections_id = up.userpermissions_id
          WHERE up.entity_id = $1 AND up.userpermissions_key = $2 AND pp.permissions = ANY($3::text[])
          LIMIT 1",
    )
    .bind(id)
    .bind(p.id)
    .bind(&perms)
    .fetch_optional(&mut *c)
    .await?;
    if user_hit.is_some() {
        return Ok(true);
    }
    let group_hit: Option<(i32,)> = sqlx::query_as(
        "SELECT 1 FROM grouppermissions gp
           JOIN permissioncollections_permissions pp ON pp.permissioncollections_id = gp.grouppermissions_id
          WHERE gp.entity_id = $1
            AND gp.grouppermissions_key IN (SELECT usergroup_id FROM user_usergroup WHERE user_id = $2)
            AND pp.permissions = ANY($3::text[])
          LIMIT 1",
    )
    .bind(id)
    .bind(p.id)
    .bind(&perms)
    .fetch_optional(&mut *c)
    .await?;
    Ok(group_hit.is_some())
}

