//! Persistence on the shogun-core schema: loading entities with their embedded
//! relations, saving them the way Hibernate does (cascades, join tables,
//! JOINED subclasses) and deleting them.

use std::collections::BTreeSet;
use std::vec::IntoIter;

use anyhow::{anyhow, bail, Result};
use serde_json::{Map, Value};
use sqlx::{PgConnection, PgPool};

use crate::model::*;

type Ext = Option<Extent>;

// ---------------------------------------------------------------------------
// Identifiers: `hibernate_sequences` row 'default', allocated in its own
// transaction (Hibernate's table generator does that, so failed requests
// still consume ids).
// ---------------------------------------------------------------------------

pub async fn alloc_ids(pool: &PgPool, n: usize) -> Result<Vec<i32>> {
    if n == 0 {
        return Ok(vec![]);
    }
    let (last,): (i64,) = sqlx::query_as(
        "UPDATE hibernate_sequences SET next_val = next_val + $1 WHERE sequence_name = 'default' RETURNING next_val",
    )
    .bind(n as i64)
    .fetch_one(pool)
    .await?;
    let first = last - n as i64 + 1;
    (0..n as i64).map(|i| i32::try_from(first + i).map_err(|_| anyhow!("id overflow"))).collect()
}

/// Counts the objects of an entity that need a fresh id: the entity itself
/// when it has none, and the cascaded children (appearance, tile grid, grid
/// extent) that the request supplies without an id.
pub trait Ids {
    fn count_new(&self) -> usize;
    fn assign(&mut self, ids: &mut IntoIter<i32>);
}

fn take(ids: &mut IntoIter<i32>) -> i32 {
    ids.next().expect("id budget")
}

impl Ids for Role {
    fn count_new(&self) -> usize {
        usize::from(self.id.is_none())
    }
    fn assign(&mut self, ids: &mut IntoIter<i32>) {
        if self.id.is_none() {
            self.id = Some(take(ids));
        }
    }
}

impl Ids for User {
    fn count_new(&self) -> usize {
        usize::from(self.id.is_none())
    }
    fn assign(&mut self, ids: &mut IntoIter<i32>) {
        if self.id.is_none() {
            self.id = Some(take(ids));
        }
    }
}

impl Ids for UserGroup {
    fn count_new(&self) -> usize {
        usize::from(self.id.is_none())
    }
    fn assign(&mut self, ids: &mut IntoIter<i32>) {
        if self.id.is_none() {
            self.id = Some(take(ids));
        }
    }
}

impl Ids for Appearance {
    fn count_new(&self) -> usize {
        usize::from(self.id.is_none())
    }
    fn assign(&mut self, ids: &mut IntoIter<i32>) {
        if self.id.is_none() {
            self.id = Some(take(ids));
            self.is_new = true;
        }
    }
}

impl Ids for Extent {
    fn count_new(&self) -> usize {
        usize::from(self.id.is_none())
    }
    fn assign(&mut self, ids: &mut IntoIter<i32>) {
        if self.id.is_none() {
            self.id = Some(take(ids));
            self.is_new = true;
        }
    }
}

impl Ids for TileGrid {
    fn count_new(&self) -> usize {
        usize::from(self.id.is_none()) + self.extent.as_ref().map(|e| e.count_new()).unwrap_or(0)
    }
    fn assign(&mut self, ids: &mut IntoIter<i32>) {
        if self.id.is_none() {
            self.id = Some(take(ids));
            self.is_new = true;
        }
        if let Some(e) = &mut self.extent {
            e.assign(ids);
        }
    }
}

impl Ids for Source {
    fn count_new(&self) -> usize {
        match self.grid() {
            Some(g) if self.touched_grid => g.count_new(),
            _ => 0,
        }
    }
    fn assign(&mut self, ids: &mut IntoIter<i32>) {
        if self.touched_grid {
            if let Some(g) = self.grid_mut() {
                g.assign(ids);
            }
        }
    }
}

impl Ids for Layer {
    fn count_new(&self) -> usize {
        let mut n = usize::from(self.id.is_none());
        if self.touched_appearance {
            if let Some(a) = &self.appearance {
                n += a.count_new();
            }
        }
        n
    }
    fn assign(&mut self, ids: &mut IntoIter<i32>) {
        if self.id.is_none() {
            self.id = Some(take(ids));
        }
        if self.touched_appearance {
            if let Some(a) = &mut self.appearance {
                a.assign(ids);
            }
        }
    }
}

impl Source {
    pub fn grid(&self) -> Option<&TileGrid> {
        match &self.kind {
            SourceKind::TileWms { tile_grid, .. } | SourceKind::Wmts { tile_grid, .. } => tile_grid.as_ref(),
            _ => None,
        }
    }

    fn grid_mut(&mut self) -> Option<&mut TileGrid> {
        match &mut self.kind {
            SourceKind::TileWms { tile_grid, .. } | SourceKind::Wmts { tile_grid, .. } => tile_grid.as_mut(),
            _ => None,
        }
    }
}

// ---------------------------------------------------------------------------
// Loading
// ---------------------------------------------------------------------------

pub async fn all_ids(c: &mut PgConnection, table: &str) -> Result<Vec<i32>> {
    // the table names are constants chosen by the caller
    let sql = format!("SELECT id FROM {table} ORDER BY id");
    let rows: Vec<(i32,)> = sqlx::query_as(&sql).fetch_all(&mut *c).await?;
    Ok(rows.into_iter().map(|r| r.0).collect())
}

pub async fn load_user(c: &mut PgConnection, id: i32) -> Result<Option<User>> {
    let row: Option<(
        Option<String>,
        Option<String>,
        Option<String>,
        Option<String>,
        Option<String>,
        Option<String>,
        Option<String>,
        bool,
    )> = sqlx::query_as(
        "SELECT p.firstname, p.lastname, p.email, p.birthday::text, p.language,
                u.accountname, u.password, u.active
           FROM users u JOIN persons p ON p.id = u.id WHERE u.id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let Some((first, last, email, birthday, language, account, password, active)) = row else {
        return Ok(None);
    };
    let roles = load_user_roles(c, id).await?;
    let groups: Vec<(i32,)> =
        sqlx::query_as("SELECT usergroup_id FROM user_usergroup WHERE user_id = $1 ORDER BY 1")
            .bind(id)
            .fetch_all(&mut *c)
            .await?;
    Ok(Some(User {
        id: Some(id),
        first_name: first,
        last_name: last,
        email,
        birthday,
        language,
        account_name: account,
        password,
        active,
        roles: Some(roles),
        user_groups: Some(groups.into_iter().map(|g| g.0).collect()),
        touched_groups: false,
    }))
}

async fn load_user_roles(c: &mut PgConnection, user_id: i32) -> Result<Vec<Role>> {
    let rows: Vec<(i32, Option<String>, Option<String>)> = sqlx::query_as(
        "SELECT r.id, r.name, r.description FROM users_roles ur JOIN roles r ON r.id = ur.role_id
          WHERE ur.user_id = $1 ORDER BY r.id",
    )
    .bind(user_id)
    .fetch_all(&mut *c)
    .await?;
    Ok(rows.into_iter().map(|(id, name, description)| Role { id: Some(id), name, description }).collect())
}

pub async fn load_group(c: &mut PgConnection, id: i32) -> Result<Option<UserGroup>> {
    let row: Option<(Option<String>, Option<i32>)> =
        sqlx::query_as("SELECT name, owner_id FROM usergroups WHERE id = $1")
            .bind(id)
            .fetch_optional(&mut *c)
            .await?;
    let Some((name, owner_id)) = row else { return Ok(None) };
    let owner = match owner_id {
        Some(o) => load_user(c, o).await?,
        None => None,
    };
    let member_ids: Vec<(i32,)> =
        sqlx::query_as("SELECT user_id FROM user_usergroup WHERE usergroup_id = $1 ORDER BY 1")
            .bind(id)
            .fetch_all(&mut *c)
            .await?;
    let mut members = Vec::new();
    for (m,) in member_ids {
        if let Some(u) = load_user(c, m).await? {
            members.push(u);
        }
    }
    let rows: Vec<(i32, Option<String>, Option<String>)> = sqlx::query_as(
        "SELECT r.id, r.name, r.description FROM usergroups_roles ugr JOIN roles r ON r.id = ugr.role_id
          WHERE ugr.usergroup_id = $1 ORDER BY r.id",
    )
    .bind(id)
    .fetch_all(&mut *c)
    .await?;
    let roles = rows.into_iter().map(|(id, name, description)| Role { id: Some(id), name, description }).collect();
    Ok(Some(UserGroup { id: Some(id), name, owner, members: Some(members), roles: Some(roles) }))
}

pub async fn load_role(c: &mut PgConnection, id: i32) -> Result<Option<Role>> {
    let row: Option<(Option<String>, Option<String>)> =
        sqlx::query_as("SELECT name, description FROM roles WHERE id = $1")
            .bind(id)
            .fetch_optional(&mut *c)
            .await?;
    Ok(row.map(|(name, description)| Role { id: Some(id), name, description }))
}

pub async fn load_layer(c: &mut PgConnection, id: i32) -> Result<Option<Layer>> {
    let row: Option<(Option<String>, Option<String>, Option<i32>, Option<i32>)> =
        sqlx::query_as("SELECT name, description, appearance_id, source_id FROM layers WHERE id = $1")
            .bind(id)
            .fetch_optional(&mut *c)
            .await?;
    let Some((name, description, appearance_id, source_id)) = row else { return Ok(None) };
    let appearance = match appearance_id {
        Some(a) => Some(load_appearance(c, a).await?.ok_or_else(|| anyhow!("dangling appearance"))?),
        None => None,
    };
    let source = match source_id {
        Some(s) => Some(load_source(c, s).await?.ok_or_else(|| anyhow!("dangling source"))?),
        None => None,
    };
    Ok(Some(Layer { id: Some(id), name, description, source, appearance, touched_appearance: false }))
}

/// Java's `Map<String,Object>` values are stored as text and read back as the
/// best matching type (`PropertyValueConverter`).
fn property_from_text(s: String) -> Value {
    if s.eq_ignore_ascii_case("true") {
        return Value::Bool(true);
    }
    if s.eq_ignore_ascii_case("false") {
        return Value::Bool(false);
    }
    let digits = s.strip_prefix('-').unwrap_or(&s);
    if !digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit()) {
        if let Ok(i) = s.parse::<i64>() {
            return Value::from(i);
        }
    }
    if let Ok(f) = s.parse::<f64>() {
        if let Some(n) = serde_json::Number::from_f64(f) {
            return Value::Number(n);
        }
    }
    Value::String(s)
}

/// Java's `Double.toString` for the values that are stored as properties.
fn java_double(f: f64) -> String {
    let a = f.abs();
    if a != 0.0 && !(1e-3..1e7).contains(&a) {
        let s = format!("{:e}", f);
        let (mant, exp) = s.split_once('e').unwrap_or((&s, "0"));
        let mant = if mant.contains('.') { mant.to_string() } else { format!("{mant}.0") };
        format!("{mant}E{exp}")
    } else if f == f.trunc() {
        format!("{:.1}", f)
    } else {
        format!("{f}")
    }
}

/// `PropertyValueConverter.convertToDatabaseColumn`: `attribute.toString()`.
pub fn property_to_text(v: &Value) -> Result<String> {
    Ok(match v {
        Value::Null => bail!("null property value"),
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => match n.as_i64() {
            Some(i) => i.to_string(),
            None => java_double(n.as_f64().unwrap_or(0.0)),
        },
        other => other.to_string(),
    })
}

pub async fn load_appearance(c: &mut PgConnection, id: i32) -> Result<Option<Appearance>> {
    let row: Option<(
        Option<String>,
        Option<bool>,
        Option<String>,
        Option<bool>,
        Option<f64>,
        Option<f64>,
        Option<String>,
        Option<f64>,
        Option<bool>,
    )> = sqlx::query_as(
        "SELECT attribution, clickable, hovertemplate, hoverable, maxresolution, minresolution, name, opacity, visible
           FROM layerappearances WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let Some((attribution, clickable, hover_template, hoverable, max_r, min_r, name, opacity, visible)) = row else {
        return Ok(None);
    };
    let props: Vec<(String, String)> =
        sqlx::query_as("SELECT property, value FROM layerappearances_properties WHERE appearance_id = $1 ORDER BY property")
            .bind(id)
            .fetch_all(&mut *c)
            .await?;
    let mut map = Map::new();
    for (k, v) in props {
        map.insert(k, property_from_text(v));
    }
    Ok(Some(Appearance {
        id: Some(id),
        is_new: false,
        attribution,
        hoverable,
        clickable,
        hover_template,
        properties: Some(map),
        name,
        max_resolution: max_r,
        min_resolution: min_r,
        opacity,
        visible,
    }))
}

pub async fn load_extent(c: &mut PgConnection, id: i32) -> Result<Option<Extent>> {
    let row: Option<(Option<f64>, Option<f64>, Option<f64>, Option<f64>)> = sqlx::query_as(
        "SELECT lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    Ok(row.map(|(llx, lly, urx, ury)| Extent {
        id: Some(id),
        is_new: false,
        lower_left: Pt::from_columns(llx, lly),
        upper_right: Pt::from_columns(urx, ury),
    }))
}

pub async fn load_grid(c: &mut PgConnection, id: i32) -> Result<Option<TileGrid>> {
    let row: Option<(Option<String>, Option<f64>, Option<f64>, Option<i32>, Option<i32>)> = sqlx::query_as(
        "SELECT type, tilegridorigin_x, tilegridorigin_y, tilesize, tilegridextent_id FROM tilegrids WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let Some((typ, ox, oy, tile_size, extent_id)) = row else { return Ok(None) };
    let is_wmts: Option<(i32,)> = sqlx::query_as("SELECT id FROM wmtstilegrids WHERE id = $1")
        .bind(id)
        .fetch_optional(&mut *c)
        .await?;
    let is_wmts = is_wmts.is_some();
    let matrix_ids = if is_wmts {
        let rows: Vec<(String,)> =
            sqlx::query_as("SELECT matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1 ORDER BY 1")
                .bind(id)
                .fetch_all(&mut *c)
                .await?;
        Some(rows.into_iter().map(|r| r.0).collect())
    } else {
        None
    };
    let res: Vec<(f64,)> =
        sqlx::query_as("SELECT resolution FROM tilegrid_resolution WHERE tilegrid_id = $1 ORDER BY idx")
            .bind(id)
            .fetch_all(&mut *c)
            .await?;
    let extent = match extent_id {
        Some(e) => load_extent(c, e).await?,
        None => None,
    };
    Ok(Some(TileGrid {
        id: Some(id),
        is_new: false,
        is_wmts,
        typ,
        origin: Pt::from_columns(ox, oy),
        extent,
        tile_size,
        resolutions: Some(res.into_iter().map(|r| r.0).collect()),
        matrix_ids,
    }))
}

pub async fn load_source(c: &mut PgConnection, id: i32) -> Result<Option<Source>> {
    let row: Option<(Option<String>, Option<String>, Option<String>, Option<String>)> =
        sqlx::query_as("SELECT name, type, url, format FROM layerdatasources WHERE id = $1")
            .bind(id)
            .fetch_optional(&mut *c)
            .await?;
    let Some((name, typ, url, format)) = row else { return Ok(None) };

    let is_tile: Option<(i32,)> = sqlx::query_as("SELECT id FROM tilewmslayerdatasources WHERE id = $1")
        .bind(id)
        .fetch_optional(&mut *c)
        .await?;
    let image_row: Option<(i32, i32, Option<String>, Option<String>, Option<String>, Option<bool>, Option<String>)> =
        sqlx::query_as(
            "SELECT height, width, version, layernames, layerstyles, requestablebypath, customrequestpath
               FROM imagewmslayerdatasources WHERE id = $1",
        )
        .bind(id)
        .fetch_optional(&mut *c)
        .await?;
    let image = image_row.map(|(height, width, version, layer_names, layer_styles, requestable, custom)| ImageFields {
        width,
        height,
        version,
        layer_names,
        layer_styles,
        requestable_by_path: requestable,
        custom_request_path: custom,
    });

    let kind = if is_tile.is_some() {
        let img = image.ok_or_else(|| anyhow!("TileWMS without image row"))?;
        let (with_tiled, grid_id): (Option<bool>, Option<i32>) =
            sqlx::query_as("SELECT request_with_tiled, tilegrid_id FROM tilewmslayerdatasources WHERE id = $1")
                .bind(id)
                .fetch_one(&mut *c)
                .await?;
        let tile_grid = match grid_id {
            Some(g) => load_grid(c, g).await?,
            None => None,
        };
        SourceKind::TileWms { img, tile_grid, request_with_tiled: with_tiled }
    } else if let Some(img) = image {
        SourceKind::ImageWms(img)
    } else if let Some((version, type_name, type_names)) = sqlx::query_as::<_, (Option<String>, Option<String>, Option<String>)>(
        "SELECT version, typename, typenames FROM wfslayerdatasources WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?
    {
        SourceKind::Wfs { version, type_name, type_names }
    } else if let Some((capabilities_url, matrix_set, projection, request_encoding, wmts_layer, wmts_style, grid_id)) =
        sqlx::query_as::<
            _,
            (
                Option<String>,
                Option<String>,
                Option<String>,
                Option<String>,
                Option<String>,
                Option<String>,
                Option<i32>,
            ),
        >(
            "SELECT capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id
               FROM wmtslayerdatasources WHERE id = $1",
        )
        .bind(id)
        .fetch_optional(&mut *c)
        .await?
    {
        let urls: Vec<(String,)> = sqlx::query_as(
            "SELECT urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1 ORDER BY 1",
        )
        .bind(id)
        .fetch_all(&mut *c)
        .await?;
        let tile_grid = match grid_id {
            Some(g) => load_grid(c, g).await?,
            None => None,
        };
        SourceKind::Wmts {
            tile_grid,
            urls: Some(urls.into_iter().map(|u| u.0).collect()),
            wmts_layer,
            wmts_style,
            projection,
            matrix_set,
            request_encoding,
            capabilities_url,
        }
    } else if let Some((cx, cy, tile_size, extent_id)) = sqlx::query_as::<_, (Option<f64>, Option<f64>, Option<i32>, Option<i32>)>(
        "SELECT center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?
    {
        let extent = match extent_id {
            Some(e) => load_extent(c, e).await?,
            None => None,
        };
        // the resolutions are Java-serialised bytes in the schema and are not mapped
        SourceKind::Xyz { center: Pt::from_columns(cx, cy), extent, resolutions: Some(vec![]), tile_size }
    } else {
        bail!("layer data source {id} has no subtype row");
    };

    Ok(Some(Source { id: Some(id), name, typ, url, format, kind, touched_grid: false }))
}

// ---------------------------------------------------------------------------
// Saving (insert when `is_new`, otherwise update; a missing row is an error,
// as Hibernate's StaleStateException is)
// ---------------------------------------------------------------------------

fn expect_one(rows: u64) -> Result<()> {
    if rows == 1 {
        Ok(())
    } else {
        bail!("expected one row, affected {rows}")
    }
}

/// Distinct ids of referenced entities, in order; a transient reference is an error.
fn ref_ids<'a, T: 'a>(items: impl Iterator<Item = &'a T>, id: impl Fn(&T) -> Option<i32>) -> Result<Vec<i32>> {
    let mut set = BTreeSet::new();
    for it in items {
        set.insert(id(it).ok_or_else(|| anyhow!("transient reference"))?);
    }
    Ok(set.into_iter().collect())
}

pub async fn save_user(c: &mut PgConnection, u: &User, is_new: bool) -> Result<()> {
    let id = u.id.ok_or_else(|| anyhow!("user without id"))?;
    let birthday = u.birthday.clone();
    if is_new {
        sqlx::query(
            "INSERT INTO persons (id, created, modified, firstname, lastname, email, birthday, language)
             VALUES ($1, now(), now(), $2, $3, $4, $5::date, $6)",
        )
        .bind(id)
        .bind(&u.first_name)
        .bind(&u.last_name)
        .bind(&u.email)
        .bind(&birthday)
        .bind(&u.language)
        .execute(&mut *c)
        .await?;
        sqlx::query("INSERT INTO users (id, accountname, active, password) VALUES ($1, $2, $3, $4)")
            .bind(id)
            .bind(&u.account_name)
            .bind(u.active)
            .bind(&u.password)
            .execute(&mut *c)
            .await?;
    } else {
        expect_one(
            sqlx::query(
                "UPDATE persons SET firstname = $2, lastname = $3, email = $4, birthday = $5::date,
                        language = $6, modified = now() WHERE id = $1",
            )
            .bind(id)
            .bind(&u.first_name)
            .bind(&u.last_name)
            .bind(&u.email)
            .bind(&birthday)
            .bind(&u.language)
            .execute(&mut *c)
            .await?
            .rows_affected(),
        )?;
        expect_one(
            sqlx::query("UPDATE users SET accountname = $2, active = $3, password = $4 WHERE id = $1")
                .bind(id)
                .bind(&u.account_name)
                .bind(u.active)
                .bind(&u.password)
                .execute(&mut *c)
                .await?
                .rows_affected(),
        )?;
    }
    if let Some(roles) = &u.roles {
        let ids = ref_ids(roles.iter(), |r| r.id)?;
        sqlx::query("DELETE FROM users_roles WHERE user_id = $1").bind(id).execute(&mut *c).await?;
        for rid in ids {
            sqlx::query("INSERT INTO users_roles (user_id, role_id) VALUES ($1, $2)")
                .bind(id)
                .bind(rid)
                .execute(&mut *c)
                .await?;
        }
    } else {
        sqlx::query("DELETE FROM users_roles WHERE user_id = $1").bind(id).execute(&mut *c).await?;
    }
    if let Some(groups) = &u.user_groups {
        let ids: BTreeSet<i32> = groups.iter().copied().collect();
        sqlx::query("DELETE FROM user_usergroup WHERE user_id = $1").bind(id).execute(&mut *c).await?;
        for gid in ids {
            sqlx::query("INSERT INTO user_usergroup (user_id, usergroup_id) VALUES ($1, $2)")
                .bind(id)
                .bind(gid)
                .execute(&mut *c)
                .await?;
        }
    } else {
        sqlx::query("DELETE FROM user_usergroup WHERE user_id = $1").bind(id).execute(&mut *c).await?;
    }
    Ok(())
}

pub async fn save_group(c: &mut PgConnection, g: &UserGroup, is_new: bool) -> Result<()> {
