    if a.is_new {
        sqlx::query(
            "INSERT INTO layerappearances (id, created, modified, attribution, clickable, hovertemplate, hoverable,
                    maxresolution, minresolution, name, opacity, visible)
             VALUES ($1, now(), now(), $2, $3, $4, $5, $6, $7, $8, $9, $10)",
