// ---------------------------------------------------------------------------
// Deleting. Hibernate removes the rows of the collections an entity owns
// (permission maps, join tables) and the JOINED subclass rows; foreign keys
// from other tables make the delete fail.
// ---------------------------------------------------------------------------

async fn delete_permission_rows(c: &mut PgConnection, id: i32) -> Result<()> {
    sqlx::query("DELETE FROM userpermissions WHERE entity_id = $1").bind(id).execute(&mut *c).await?;
