    delete_permission_rows(c, id).await?;
    expect_one(sqlx::query("DELETE FROM users WHERE id = $1").bind(id).execute(&mut *c).await?.rows_affected())?;
    expect_one(sqlx::query("DELETE FROM persons WHERE id = $1").bind(id).execute(&mut *c).await?.rows_affected())?;
