        assert_eq!(java_double(3.0), "3.0");
        assert_eq!(java_double(1e10), "1.0E10");
        assert_eq!(java_double(0.0001), "1.0E-4");
    }

    #[test]
    fn property_round_trip_types() {
        assert_eq!(property_from_text("true".into()), Value::Bool(true));
        assert_eq!(property_from_text("12".into()), Value::from(12i64));
        assert_eq!(property_from_text("1.5".into()), serde_json::json!(1.5));
        assert_eq!(property_from_text("abc".into()), Value::String("abc".into()));
    }
}

