//! The six REST resources: how each Java entity maps onto the generic
//! operations in `entity.rs`.

use anyhow::Result;
use serde_json::{Map, Value};
use sqlx::PgConnection;

use crate::entity::Entity;
use crate::model::*;
use crate::perm::Kind;
use crate::store;

impl Entity for User {
    const KIND: Kind = Kind::User;
    const TABLE: &'static str = "users";
    const FIELDS: &'static [(&'static str, FType)] = USER_FIELDS;

    fn parse_fresh(v: &Value) -> Parse<Self> {
        User::parse_fresh(v)
    }
    fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        User::apply(self, o)
    }
    fn to_json(&self) -> Value {
        self.json()
    }
    fn id(&self) -> Option<i32> {
        self.id
    }
    fn field(&self, name: &str) -> FVal {
        User::field(self, name)
    }
    fn project(&self, fields: &[&str]) -> Self {
        User::project(self, fields)
    }
    fn touched_group_refs(&self) -> Vec<i32> {
        if self.touched_groups {
            self.user_groups.clone().unwrap_or_default()
        } else {
            vec![]
        }
    }
    async fn load(c: &mut PgConnection, id: i32) -> Result<Option<Self>> {
        store::load_user(c, id).await
    }
    async fn save(&self, c: &mut PgConnection, is_new: bool) -> Result<()> {
        store::save_user(c, self, is_new).await
    }
    async fn delete(&self, c: &mut PgConnection) -> Result<()> {
        store::delete_user(c, self.id.unwrap_or_default()).await
    }
}

impl Entity for UserGroup {
    const KIND: Kind = Kind::Group;
    const TABLE: &'static str = "usergroups";
    const FIELDS: &'static [(&'static str, FType)] = GROUP_FIELDS;

    fn parse_fresh(v: &Value) -> Parse<Self> {
        UserGroup::parse_fresh(v)
    }
    fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
        UserGroup::apply(self, o)
    }
    fn to_json(&self) -> Value {
        self.json()
    }
    fn id(&self) -> Option<i32> {
        self.id
    }
    fn field(&self, name: &str) -> FVal {
        UserGroup::field(self, name)
    }
    fn project(&self, fields: &[&str]) -> Self {
        UserGroup::project(self, fields)
    }
    fn touched_group_refs(&self) -> Vec<i32> {
        let mut out = vec![];
        if let Some(o) = &self.owner {
            out.extend(o.touched_group_refs());
        }
        for m in self.members.iter().flatten() {
            out.extend(m.touched_group_refs());
        }
        out
    }
    async fn load(c: &mut PgConnection, id: i32) -> Result<Option<Self>> {
        store::load_group(c, id).await
    }
    async fn save(&self, c: &mut PgConnection, is_new: bool) -> Result<()> {
        store::save_group(c, self, is_new).await
    }
    async fn delete(&self, c: &mut PgConnection) -> Result<()> {
        store::delete_group(c, self.id.unwrap_or_default()).await
    }
}

impl Entity for Role {
    const KIND: Kind = Kind::Role;
    const TABLE: &'static str = "roles";
    const FIELDS: &'static [(&'static str, FType)] = ROLE_FIELDS;

    fn parse_fresh(v: &Value) -> Parse<Self> {
        Role::parse_fresh(v)
    }
    fn apply(&mut self, o: &Map<String, Value>) -> Parse<()> {
