//! HTTP layer: routing of `/rest/...` (as Spring MVC maps it), the Basic-auth
//! gate in front of it, and the two nested endpoints.

use std::sync::Arc;

use axum::body::{to_bytes, Body};
use axum::extract::{Request, State};
use axum::http::{header, HeaderMap, Method, StatusCode};
use axum::response::Response;
use axum::Router;
use serde_json::Value;
use sqlx::PgPool;

use crate::auth::{self, Refusal};
use crate::entity::{self, Out};
use crate::model::*;
use crate::perm::{allowed, Kind, Perm, Principal};
use crate::resources::*;
use crate::store;

pub struct AppState {
    pub pool: PgPool,
}

pub fn router(state: Arc<AppState>) -> Router {
    Router::new().fallback(handle).with_state(state)
}

const JSON_CONTENT_TYPE: &str = "application/json;charset=UTF-8";
const MAX_BODY: usize = 16 * 1024 * 1024;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Res {
    Users,
    Groups,
    Roles,
    Layers,
    Sources,
    Appearances,
}

impl Res {
    fn parse(s: &str) -> Option<Res> {
        Some(match s {
            "users" => Res::Users,
            "groups" => Res::Groups,
            "roles" => Res::Roles,
            "layers" => Res::Layers,
            "layerdatasources" => Res::Sources,
            "layerappearances" => Res::Appearances,
            _ => return None,
        })
    }
}

enum Route {
    List(Res),
    Filter(Res),
    Create(Res),
    Item(Res, i32, Method),
    UserGroups(i32),
    GroupUsers(i32),
}

fn status_only(code: StatusCode) -> Response {
    let mut r = Response::new(Body::empty());
    *r.status_mut() = code;
    r
}

fn json_response(code: StatusCode, value: &Value) -> Response {
    let mut r = Response::new(Body::from(value.to_string()));
    *r.status_mut() = code;
    r.headers_mut().insert(header::CONTENT_TYPE, JSON_CONTENT_TYPE.parse().expect("header"));
    r
}

fn refusal(r: Refusal) -> Response {
    match r {
        Refusal::Unauthorized => {
            let mut resp = status_only(StatusCode::UNAUTHORIZED);
            resp.headers_mut()
                .insert(header::WWW_AUTHENTICATE, "Basic realm=\"SHOGun Realm\"".parse().expect("header"));
            resp
        }
        Refusal::Forbidden => status_only(StatusCode::FORBIDDEN),
    }
}

/// Path normalisation: a trailing slash names the same handler.
fn normalise(path: &str) -> &str {
    let mut p = path;
    while p.len() > 1 && p.ends_with('/') {
        p = &p[..p.len() - 1];
    }
    p
}

/// Matches the request to one of the handlers of the controllers.
/// `Err` carries the status Spring would answer with.
fn route(method: &Method, path: &str) -> Result<Route, StatusCode> {
    let segs: Vec<&str> = path.trim_start_matches('/').split('/').collect();
    if segs.first() != Some(&"rest") {
        return Err(StatusCode::NOT_FOUND);
    }
    let res = segs.get(1).and_then(|s| Res::parse(s));
    let Some(res) = res else { return Err(StatusCode::NOT_FOUND) };
    let rest = &segs[2..];
    let is_get = *method == Method::GET;
    match rest {
        [] => match *method {
            Method::GET => Ok(Route::List(res)),
            Method::POST => Ok(Route::Create(res)),
            _ => Err(StatusCode::METHOD_NOT_ALLOWED),
        },
