            if !is_get {
                return Err(StatusCode::METHOD_NOT_ALLOWED);
            }
            Ok(Route::UserGroups(id.parse().map_err(|_| StatusCode::BAD_REQUEST)?))
        }
        [id, sub] if res == Res::Groups && *sub == "users" => {
            if !is_get {
                return Err(StatusCode::METHOD_NOT_ALLOWED);
            }
            Ok(Route::GroupUsers(id.parse().map_err(|_| StatusCode::BAD_REQUEST)?))
        }
        _ => Err(StatusCode::NOT_FOUND),
    }
}

